arguments.argument:
if(vspeed > 0)
{
    var chuteIndex;
    chuteIndex = ceil(vspeed/10*3)-1;
    image_index = chuteIndex + (team==TEAM_BLUE)*3;
    sprite_index = ParachuteSentry;
}
else
{
    if (team == TEAM_BLUE)
        sprite_index = DispenserBlueS;
    if (team == TEAM_RED)
        sprite_index = DispenserRedS;
}
var xr, yr, color;
xr = round(x);
yr = round(y);

if team == TEAM_RED color = c_red;
else if team == TEAM_BLUE color = c_blue;
else color = c_white;
	if built {
		with Player {
    		if instance_exists(object) {
	    		if ((team == other.team || class == CLASS_SPY) && object != -1) {
	    			//FIX: Moved check below other check to avoid checking not yet existant variable
	    			if (!object.cloak) {
		    		with other if(point_distance(x,y,other.object.x, other.object.y)<=maxHealDistance) {
			    		if(collision_line(xr,yr, other.object.x, other.object.y, Obstacle, true, true)<0) {
				    			draw_set_alpha(0.3);
					    		draw_line_width_color(xr, yr, other.object.x, other.object.y, 5, color, color);	
					    }
					}
				}
				}
			}
		}
	}
draw_set_alpha(1);
if global.myself.team == team draw_healthbar(xr-10, yr-30, xr+10, yr-25,hp*100/maxHp,c_black,c_red,c_green,0,true,true);
if (built && hp < .75 * maxHp) draw_sprite_part_ext(FlameS, random(4), 0, 0, 21, 9, xr-21/2, yr-15, 1, 1, c_white, 1 - (hp / maxHp));
draw_sprite_ext(sprite_index,image_index,xr,yr,image_xscale,image_yscale,image_angle,c_white,1);


if(distance_to_point(mouse_x, mouse_y)<25 && global.myself.team == team) {
    draw_set_alpha(1);   
    draw_set_halign(fa_center);
    draw_set_valign(fa_bottom); 
    if(team==TEAM_RED) {
        draw_set_color(c_red);
    } else {
        draw_set_color(c_blue);
    }
    draw_text(xr, yr-45, ownerPlayer.name + "'s");
    draw_text(xr, yr-35, "Provider");
}
